// intent: Test that json_view correctly parses a valid negative integer number starting with a minus sign followed by a digit.
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>
int main() {
    try {
        std::string s = "-42";
        auto doc = nlohmann::json_document::parse(s.data(), s.data() + s.size());
        nlohmann::json_view view(doc);
        std::cout << view.is_number() << " " << view.get<int>() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    }
}
